using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly Payments.PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new Payments.PaymentGateway(_provider);
    }

    #region Constructor Tests

    [TestMethod]
    public void Constructor_NullProvider_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => new Payments.PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    #endregion

    #region ChargeAsync Tests

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_ReturnsSuccessfulCharge()
    {
        // Arrange
        _provider.ChargeResult = new ChargeResult("ch_123", true);

        // Act
        var result = await _gateway.ChargeAsync("tok_valid", 49.99m);

        // Assert
        Assert.IsNotNull(result);
        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidRequest_PassesParametersToProvider()
    {
        _provider.ChargeResult = new ChargeResult("ch_abc", true);

        await _gateway.ChargeAsync("tok_card", 100.00m);

        Assert.AreEqual("tok_card", _provider.LastCardToken);
        Assert.AreEqual(100.00m, _provider.LastAmount);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? cardToken)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10m));
        Assert.AreEqual("cardToken", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-0.01)]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    public async Task ChargeAsync_AmountExceedsMaximum_ThrowsArgumentOutOfRange()
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_valid", 1_000_000m));
        Assert.AreEqual("amount", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum valid amount")]
    [DataRow(999_999.99, DisplayName = "Maximum valid amount")]
    [DataRow(50.00, DisplayName = "Typical amount")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        _provider.ChargeResult = new ChargeResult("ch_boundary", true);

        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderDeclines_ReturnsFailedCharge()
    {
        _provider.ChargeResult = new ChargeResult("ch_declined", false);

        var result = await _gateway.ChargeAsync("tok_valid", 25.00m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual("ch_declined", result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        _provider.ShouldHonorCancellation = true;

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_valid", 10m, cts.Token));
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessfulRefund()
    {
        _provider.RefundResult = new RefundResult("rf_456", true);

        var result = await _gateway.RefundAsync("ch_123");

        Assert.IsNotNull(result);
        Assert.AreEqual("rf_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        var ex = await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
        Assert.AreEqual("chargeId", ex.ParamName);
    }

    [TestMethod]
    public async Task RefundAsync_ProviderFails_ReturnsFailedRefund()
    {
        _provider.RefundResult = new RefundResult("rf_failed", false);

        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_PassesChargeIdToProvider()
    {
        _provider.RefundResult = new RefundResult("rf_ok", true);

        await _gateway.RefundAsync("ch_original_id");

        Assert.AreEqual("ch_original_id", _provider.LastChargeId);
    }

    #endregion

    #region ProcessWebhook Tests

    [TestMethod]
    [DataRow("charge.succeeded", "Charge confirmed")]
    [DataRow("charge.failed", "Charge failed")]
    [DataRow("refund.completed", "Refund confirmed")]
    public void ProcessWebhook_KnownEventType_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, """{"id":"evt_1"}""");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    [TestMethod]
    public void ProcessWebhook_UnknownEventType_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("unknown.event", """{"id":"evt_2"}""");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("unknown.event", result.Message);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidEventType_ThrowsArgumentException(string? eventType)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, "{}"));
        Assert.AreEqual("eventType", ex.ParamName);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void ProcessWebhook_InvalidPayload_ThrowsArgumentException(string? payload)
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
